def magic_denoise(X, **kwargs):
    X = np.asarray(X, dtype=float)
    X = np.nan_to_num(X, nan=0.0, posinf=0.0, neginf=0.0)
    X = np.maximum(X, 0.0)

    def objective_func(denoised):
        normalized_counts = normalize(denoised, axis=1, norm='l1')
        squared_errors = squared_error(normalized_counts, X)
        return np.sum(squared_errors)

    def squared_error(predicted, actual):
        return ((predicted - actual) ** 2).sum(axis=-1) / len(actual)

    initial_guess = np.mean(X, axis=0)
    result = minimize(objective_func, initial_guess, bounds=(0, None))
    denoised = result.x.reshape(X.shape)

    def poisson_loss_function(denoised):
        normalized_counts = normalize(denoised, axis=1, norm='l1')
        scaled_counts = np.log(1 + normalized_counts)
        return -np.sum(poisson.logpmf(X.flatten(), scaled_counts).flatten())

    poisson_loss = poisson_loss_function(denoised)
    if poisson_loss < 0.031739 * (0.257575 - 0.031739) / 0.257575:
        raise ValueError("Poisson constraint violated")

    denoised[X > 1] = 0.0
    return denoised
